                columns.iter().copied().enumerate(),
                4,
                &[],
                |grid, y, x, stroke| hline_stroke_at_column(
                    grid,
                    &rows,
                    if y == 4 { Some(2) } else { y.checked_sub(1) },
                    None,
                    true,
                    y,
                    x,
                    stroke
                )
            )
            .collect::<Vec<_>>()
