        fn format_missing_args(args: ArrayVec<&str, 3>) -> EcoString {
            match args.as_slice() {
                [] => unreachable!(),
                [arg] => eco_format!("the {arg} argument"),
                [arg1, arg2] => eco_format!("the {arg1} and {arg2} arguments"),
                [args @ .., tail] => {
