use crate::foundations::{Value, elem};
use crate::introspection::Locatable;

/// Exposes a value to the query system without producing visible content.
///
/// This element can be retrieved with the @query function and from the command
/// line with @query:command-line-queries[`typst query`]. Its purpose is to
/// expose an arbitrary value to the introspection system. To identify a
/// metadata value among others, you can attach a @label to it and query for
/// that label.
///
/// The `metadata` element is especially useful for command line queries because
/// it allows you to expose arbitrary values to the outside world.
///
/// ```example
/// // Put metadata somewhere.
/// #metadata("This is a note") <note>
///
/// // And find it from anywhere else.
/// #context {
///   query(<note>).first().value
/// }
/// ```
#[elem(Locatable)]
pub struct MetadataElem {
    /// The value to embed into the document.
    #[required]
    pub value: Value,
}

//! Interaction between document parts.

mod convergence;
mod counter;
#[path = "here.rs"]
mod here_;
mod introspector;
#[path = "locate.rs"]
mod locate_;
mod location;
mod locator;
mod metadata;
mod position;
#[path = "query.rs"]
mod query_;
mod state;
mod tag;

pub use self::convergence::*;
pub use self::counter::*;
pub use self::here_::*;
pub use self::introspector::*;
pub use self::locate_::*;
pub use self::location::*;
pub use self::locator::*;
pub use self::metadata::*;
pub use self::position::*;
pub use self::query_::*;
pub use self::state::*;
pub use self::tag::*;

use crate::foundations::Scope;

/// Hook up all `introspection` definitions.
pub fn define(global: &mut Scope) {
    global.start_category(crate::Category::Introspection);
    global.define_type::<Location>();
    global.define_type::<Counter>();
    global.define_type::<State>();
    global.define_elem::<MetadataElem>();
    global.define_func::<here>();
    global.define_func::<query>();
    global.define_func::<locate>();
    global.reset_category();
}

