code {
  font-family: "Cascadia Mono", "Courier New", Courier, monospace;
  font-size: 15px;
}

main {
  padding: 0px 32px;
}

h1 {
  font-weight: 700;
  font-size: 36px;
  margin-block-end: 24px;
}

h1 small {
  font-size: 24px;
  margin-inline-start: 0.2em;
  color: #565565;
}

h3 {
  font-size: inherit;
}

p {
  margin-block-start: 0.5rem;
  margin-block-end: 0.5rem;
}

address {
  font-style: inherit;
}

strong {
  font-weight: 600;
}

section > * > h2:first-child {
  margin-block-start: 0;
}

main > ol > li,
main > ul > li {
  margin-block-end: 4px;
  margin-block-start: 4px;
}

.previewed-code {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-block-end: 24px;
}

p + .previewed-code,
div + .previewed-code {
  margin-block-start: 24px;
}

.previewed-code > * {
  flex-basis: 0;
  flex-grow: 1;
  min-width: 250px;
}

.previewed-code pre,
pre:has(code) {
  overflow-x: auto;
}

.previewed-code pre.big {
  box-sizing: border-box;
  min-width: 100%;
}

.preview {
  background: #e4e5ea;
  border-radius: 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 12px 16px;
  gap: 16px;
}

.preview > * {
  background: #fff;
  box-shadow: 0px 4px 12px rgba(89, 85, 101, 0.2);
  max-width: 100%;
  max-height: 100%;
  width: auto;
  height: auto;
}

pre,
.code-definition {
  border-radius: 6px;
  box-shadow: 0px 4px 12px rgba(89, 85, 101, 0.2);
  padding: 16px;
  margin: 0px;
}

.info-box {
  background: #e8f9ff;
  border: #007aff 1px solid;
  border-radius: 6px;
  padding: 12px 16px 8px 16px;
}

.info-box::before {
  content: "Info";
  display: block;
  text-transform: uppercase;
  font-weight: 600;
  font-size: 14px;
  margin-block-end: 8px;
  text-align: left;
  color: #001666;
}

.typ-comment,
.hljs-comment {
  color: var(--text-c-comment);
}

.typ-escape {
  color: var(--text-c-escape);
}

.typ-strong {
  font-weight: bold;
}

.typ-emph {
  font-style: italic;
}

.typ-link {
  text-decoration: underline;
}
.typ-raw {
  color: var(--text-c-monospace);
}

.typ-label {
  color: var(--text-c-escape);
}

.typ-ref {
  color: var(--text-c-escape);
}

.typ-heading {
  font-weight: bold;
  text-decoration: underline;
}

.typ-marker {
  color: var(--text-c-list-marker);
}

.typ-term {
  font-weight: bold;
}

.typ-math-delim {
  color: var(--text-c-math-delim);
}

.typ-math-op {
  color: var(--text-c-math-op);
}

.typ-key,
.hljs-tag .hljs-name,
.hljs-section {
  color: var(--text-c-keyword);
}

.typ-num {
  color: var(--text-c-number);
}

.typ-str,
.hljs-string {
  color: var(--text-c-string);
}

.typ-func,
.hljs-attr {
  color: var(--text-c-func);
}

.typ-pol {
  color: var(--text-c-interpolated);
}

.hidden {
  display: none !important;
}

@media screen and (max-width: 768px) {
  html,
  body {
    font-size: 16px;
  }

  body section {
    padding: 40px 24px 40px 24px;
  }

  main {
    padding: 0px 24px;
  }
}

@media screen and (max-width: 365px) {
  .previewed-code > * {
    min-width: 120px;
  }
}

@media (prefers-contrast: more) {
  input::placeholder,
  input::-moz-placeholder {
    opacity: 0.8;
    color: #21212a;
  }
}

files.docs/assets/docs.css:
/* Page setup */

/** General note: The docs class is used in some places to increase the
 * specificity. */

body.docs {
  font-size: 16px;
}

body.docs > .main-grid {
  max-width: unset;
  padding: 32px;
}

.main-grid {
  display: grid;
  grid-template-columns: minmax(auto, 184px) minmax(auto, 800px) minmax(
      auto,
      144px
    );
  gap: 36px;
  justify-content: center;
}

@media screen and (max-width: 1024px) {
  .main-grid {
    display: grid;
    grid-template-columns: minmax(auto, 184px) minmax(auto, 784px);
    gap: 28px;
    justify-content: center;
  }
}

@media screen and (max-width: 695px) {
  .main-grid {
    display: block;
    padding-inline: 24px;
  }

  .docs main {
    padding-inline: 0px;
  }
}

@media screen and (max-width: 365px) {
  .main-grid {
    max-width: unset;
    padding: 12px;
  }
}

/* Built-in element styles */

h1 {
  display: flex;
  align-items: baseline;
  gap: 16px;
}

h2,
h3,
h4 {
  margin-block-start: 32px;
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px 32px;
}

h2 {
  gap: 8px;
}

h3 {
  margin-block-end: 12px;
}

h4 {
  margin-block-start: 24px;
  margin-block-end: 12px;
}

h2 + h3 {
  margin-block-start: 0px !important;
}

h1 code,
h2 code,
h3 code,
h4 code {
  font-size: unset;
}

h1 small,
h2 small {
  display: inline-flex;
  gap: 8px;
  color: #565565;
  font-style: italic;
  font-size: 14px !important;
}

h1 small {
  transform: translateY(-4px);
}

h2 small {
  transform: translateY(-2px);
}

h3 small,
h4 small {
  display: inline-flex;
  gap: 4px;
  color: #565565;
  font-style: italic;
  font-size: 12px;
}

h3 small svg {
  margin-bottom: -1px;
}

@media screen and (max-width: 695px) {
  h2 small,
  h3 small {
    align-items: center;
  }

  h2 small svg,
  h3 small svg {
    margin-bottom: -2px;
    margin-left: -2px;
    padding: 4px;
  }
}

li p + ul,
li p + ol {
  margin-block-start: -0.5rem;
}

ul ul {
  padding-inline-start: 24px;
}

main > ul {
  padding-inline-start: 40px;
  margin-block: 16px;
  padding-block: 0px;
}

main > ul > li::marker {
  content: "–   ";
}

dl {
  padding-inline-start: 32px;
  margin-block: 16px;
}

dt code {
  font-size: 19px;
}

dt,
dd {
  margin-block-end: 16px;
  margin-inline: 0px;
}

main table {
  border-collapse: collapse;
  margin-block: 16px;
  width: 100%;
}

main table thead {
  text-align: left;
  font-weight: 600;
}

main table thead {
  border-bottom: 1px solid #bdbfcc;
}

main table td,
main table th {
  padding: 4px 8px;
}

main table td p:first-child {
  margin-block-start: 0;
}

main table td p:last-child {
  margin-block-end: 0;
}

main > img,
main > p > img {
  max-width: 100%;
  margin-block: 8px;
  width: auto;
  height: auto;
}

main > pre {
  margin-block: 24px;
}

p > code {
  white-space: nowrap;
}

.a11y li code:first-child {
  white-space: normal;
}

.a11y p code:first-child {
  white-space: normal;
}

kbd {
  background-color: #eee;
  border-radius: 4px;
  border: 1px solid #b4b4b4;
  box-shadow:
    0 1px 1px rgba(0, 0, 0, 0.2),
    0 2px 0 0 rgba(255, 255, 255, 0.7) inset;
  display: inline-block;
  font-size: 0.85em;
  line-height: 1;
  padding: 2px 4px;
  white-space: nowrap;
}

/* Footnote components */

section[role="doc-endnotes"] {
  position: relative;
  margin-block-start: 24px;
  padding-block-start: 12px;
}

section[role="doc-endnotes"]::before {
  content: "";
  position: absolute;
  width: 10em;
  max-width: 90%;
  height: 1px;
  top: 0px;
  display: block;
  background: var(--border-secondary);
}

section[role="doc-endnotes"] ol {
  list-style-type: none;
  margin-block: 0;
  padding-inline-start: 24px;
}

section[role="doc-endnotes"] li {
  position: relative;
}

section[role="doc-endnotes"] ol sup[role="doc-backlink"] {
  position: absolute;
  top: -0.25em;
  left: -1em;
}

sup[role="doc-noteref"] {
  position: relative;
  top: -0.1rem;
  font-size: 0.75rem;
  vertical-align: top;
}

/* Code example components */

.code-definition + h4,
.previewed-code + h4 {
  margin-block-start: 28px;
}

.code-definition {
  white-space: nowrap;
  overflow-x: auto;
}

.code-definition + .previewed-code {
  margin-block-start: 16px;
}

.code-definition + .folding-example {
  margin-block-start: 8px;
}

.folding-example + .code-definition {
  margin-block-start: 16px;
}

.folding-example summary {
  display: inline-flex;
  gap: 8px;
  font-size: 13px;
  color: #565565;
  padding: 8px 8px 8px 0;
  cursor: pointer;
  user-select: none;
  border-radius: 6px;
  transition: ease 0.1s background-color;
}

.folding-example summary:active {
  background-color: #d7d9e0;
}

.folding-example summary::marker,
.folding-example summary::-webkit-details-marker {
  display: none;
  content: "";
}

.folding-example summary img {
  transition: ease 0.2s transform;
}

.folding-example[open] summary img {
  transform: rotate(90deg);
}

.folding-example > div {
  margin-top: 6px;
}

/* Chain link component */

a.chain img {
  margin-bottom: -2px;
}

/* Search component */

.search {
  position: relative;
  display: flex;
  border-radius: 4px;
}

.search > img {
  position: absolute;
  top: 7px;
  left: 8px;
}

.search input {
  border: 1px solid #bdbfcc;
  border-radius: 4px;
  padding: 4px 0px 4px 28px;
  color: inherit;
  background: #fdfdfd;
  line-height: 1.5;
  appearance: none;
  box-sizing: border-box;
  width: 100%;
  font-size: 14px;
  font-family: inherit;
}

.search input::-webkit-search-cancel-button {
  display: none;
}

.search input:focus {
  outline: none;
  box-shadow: inset 0 0 0 2px #007aff;
}

.search input:focus-visible,
.search input:focus {
  box-shadow: none;
}

.search input:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px #007aff;
}

/* Shadow component */

figure {
  max-width: 100%;
  margin: 24px auto;
}

figure.shadow {
  box-shadow: 0 4px 12px rgb(89 85 101 / 20%);
}

figure img {
  max-width: 100%;
  height: auto;
}

.side-by-side {
  display: flex;
  flex-direction: row;
  gap: 8px 16px;
  width: 100%;
  flex-wrap: wrap;
  margin: 24px auto;
}

.side-by-side figure {
  flex-grow: 1;
}

/* Tooltip component */

.tooltip-context {
  position: relative;
}

div[role="tooltip"] {
  display: none;
  opacity: 0;
  transition: opacity 0.1s ease;
  position: absolute;
  font-size: 14px;
  color: #19181f;
  font-weight: normal;
  background: #eff0f3;
  border-radius: 6px;
  padding: 12px;
  font-style: normal;
  width: 256px;
  left: -120px;
  box-sizing: border-box;
  top: 26px;
  box-shadow:
    0px 4px 12px rgba(89, 85, 101, 0.2),
    0px 4px 24px rgba(89, 85, 101, 0.3);
  z-index: 1;
  pointer-events: none;
}

h2 div[role="tooltip"] {
  top: 36px;
}

div[role="tooltip"]:not(.mobile)::after {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 0;
  height: 0;
  border: 8px solid transparent;
  border-bottom-color: #eff0f3;
  border-top: 0;
  margin-left: -8px;
  margin-top: -8px;
}

/* Pill component */

.pill {
  display: inline-block;
  padding: 2px 4px;
  border-radius: 4px;
  font-family: "Cascadia Mono", "Courier New", Courier, monospace;
  font-size: 14px;
  font-weight: normal;
  white-space: nowrap;
}

a.pill {
  color: inherit !important;
  text-decoration: none !important;
}

.pill + .pill {
  margin-inline-start: 4px;
}

.pill-con {
  background: #a6ebe6;
}

.pill-str {
  background: #d1ffe2;
}

.pill-kw {
  background: #ffcbc4;
  background: color(display-p3 1 0.83 0.8);
}

.pill-num {
  background: #ffedc1;
  background: color(display-p3 1 0.93 0.77);
}

.pill-obj {
  background: #eff0f3;
}

.pill-collect {
  background: #f9dfff;
  background: color(display-p3 0.97 0.88 1);
}

.pill-fn {
  background: #d1d4fd;
}

.pill-meta {
  background: #c6d6ec;
}

.pill-layout {
  background: #a6eaff;
}

.pill-date::before {
  content: "";
  display: block;
  background-image: conic-gradient(
    from 30deg,
    #020513ff 0%,
    #041529ff 7%,
    #a07aaaff 18%,
    #a6aff6ff 28%,
    #89c8e5ff 35%,
    #b7daecff 66%,
    #dcac68ff 73%,
    #47232dff 79%,
    #041529ff 89%,
    #020513ff 100%
  );
  width: max(60em, 50vmax);
  height: max(60em, 50vmax);
  left: calc(max(60em, 50vmax) / -2.5);
  top: calc(max(60em, 50vmax) / -2.5);
  margin: auto;
  position: absolute;
  animation: 120s infinite linear day-bg;
  z-index: -1;
  opacity: 0.25;
}

.pill-date {
  position: relative;
  overflow: hidden;
  vertical-align: text-bottom;
  z-index: 0;
}

.pill-tiling {
  background: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 0.4em,
    #c6feff 0,
    #c6feff 0.8em
  );
  background-color: #ffd2ec;
  background: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 0.4em,
    color(display-p3 0.82 0.99 1) 0,
    color(display-p3 0.82 0.99 1) 0.8em
  );
  background-color: color(display-p3 1 0.83 0.92);
}

@keyframes day-bg {
  from {
    rotate: 40deg;
  }

  to {
    rotate: 400deg;
  }
}

.pill-col {
  background: rgb(124, 213, 255);
  background: linear-gradient(
    83deg,
    rgba(124, 213, 255, 1) 0%,
    rgba(166, 251, 202, 1) 33%,
    rgba(255, 243, 124, 1) 66%,
    rgba(255, 164, 157, 1) 100%
  );
}

h1 .pill {
  font-size: 34px;
  border-radius: 12px;
  padding: 4px 12px;
}

h3 code + .pill,
h4 code + .pill {
  margin-inline-start: 16px;
}

/* Navigation breadcrumbs */

.breadcrumbs {
  list-style: none;
  padding: 0px;
  display: flex;
  gap: 4px;
  text-decoration: none;
  align-items: center;
}

.breadcrumbs > * {
  display: block;
}

.breadcrumbs .root {
  display: block;
  background: #eff0f3;
  width: 24px;
  height: 24px;
  padding: 4px;
  box-sizing: border-box;
  display: flex;
  border-radius: 6px;
}

.breadcrumbs a:link {
  color: inherit;
  text-decoration: inherit;
}

.breadcrumbs a:hover,
.breadcrumbs a:active,
.breadcrumbs a:focus {
  text-decoration: underline;
}

.breadcrumbs .root:hover,
.breadcrumbs .root:has(a:focus) {
  background: #e4e5ea;
}

.breadcrumbs .root:has(a:active) {
  background: #d7d9e0;
}

.breadcrumbs li > img {
  margin-bottom: -3px;
}

@media screen and (max-width: 695px) {
  .breadcrumbs {
    overflow-x: auto;
  }
}

/* Left side bar, collapsible on mobile */

.hamburger,
.close {
  display: none;
  border: none;
  background: none;
  padding: 8px;
  width: 16px;
  height: 16px;
  appearance: none;
  border-radius: 4px;
  box-sizing: content-box;
}

@media screen and (max-width: 695px) {
  .hamburger,
  .close {
    display: block;
  }
}

/* Folding navigation in left sidebar */

nav.folding {
  margin: 0;
  padding: 12px;
  padding-top: 18px;
  padding-inline-end: 4px;
  margin: 0;
  opacity: 1;
  transition:
    ease 0.2s max-height,
    ease 0.2s opacity;
}

nav.folding > ul a {
  display: block;
  padding: 2.5px 16px 2.5px 8px;
  border-radius: 6px;
}

nav.folding li {
  position: relative;
}

nav.folding li > button {
  display: block;
  position: absolute;
  top: 1px;
  right: 1px;
  padding: 0px;
  border: 0px;
  background: #fdfdfd;
  width: 24px;
  height: 24px;
  padding: 4px;
  border-radius: 5px;
}

nav.folding li:hover > button {
  display: block;
}

nav.folding li > button:hover {
  background: #e4e5ea;
}

nav.folding li > button:focus-visible,
nav.folding li > a:focus-visible {
  outline: 2px solid #007aff80;
}

nav.folding li > button:active {
  background: #d7d9e0;
}

nav.folding li > button:focus {
  display: block;
}

nav.folding li[aria-expanded="true"] > button {
  background: #eff0f3;
  display: block;
  transform: rotate(90deg);
}

nav.folding li[aria-expanded="true"] > a {
  background: #eff0f3;
}

nav.folding li li:last-child {
  margin-block-end: 8px;
}

nav.folding > ul {
  padding-inline-start: 0px !important;
}

nav.folding a[aria-current="page"] {
  color: #11566c;
  font-weight: 600;
  position: relative;
}

nav.folding a[aria-current="page"]:after {
  content: "";
  position: absolute;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #11566c;
  right: 10px;
  top: 11px;
  margin-block: auto;
}

nav.folding .category {
  padding: 8px 8px 0px 8px;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 600;
  color: #565565;
}

nav.folding a,
nav.folding .category {
  margin-block-end: 4px;
}

@media (hover: hover) {
  nav.folding li > button {
    display: none;
  }
}

nav.folding ul {
  list-style: none;
  padding-inline-start: 16px;
}

nav.folding > ul > li > ul > li:last-child {
  margin-block-end: 12px;
}

nav.folding > ul > li > a {
  margin-block-end: 12px;
}

nav.folding ul.animated,
nav.folding ul.animated ul {
  transition:
    ease 0.2s max-height,
    ease 0.2s opacity;
}

@media (prefers-reduced-motion) {
  nav.folding ul.animated,
  nav.folding ul.animated ul {
    transition: none;
  }
}

nav.folding .title-row {
  display: none;
}

nav.folding .title-row svg {
  color: #239dad;
}

nav.folding .title-row span {
  font-size: 18px;
  color: #565565;
  display: block;
  padding-bottom: 4px;
}

nav.folding .close {
  position: absolute;
  top: 24px;
  left: 24px;
}

@media screen and (max-width: 695px) {
  nav.folding {
    display: block;
    opacity: 0;
    position: fixed;
    top: 0px;
    left: 0px;
    bottom: 0px;
    width: min(184px, calc(100vw - 48px));
    background: #fdfdfd;
    padding: 24px;
    padding-top: 72px;
    box-shadow:
      0px 4px 12px rgba(89, 85, 101, 0.2),
      0px 4px 24px rgba(89, 85, 101, 0.3);
    z-index: 8;
    overflow: hidden auto;
    max-height: 100vh;
    transition: ease transform 0.2s;
  }

  @supports (max-height: 100dvh) {
    nav.folding {
      max-height: 100dvh;
    }
  }

  nav.folding .title-row {
    display: block;
    padding: 8px;
  }

  @media (prefers-reduced-motion: reduce) {
    nav.folding {
      transition: none !important;
    }
  }

  nav.folding.mobile-hidden {
    display: none;
  }
}

nav.folding .search-results {
  border-bottom: 1px solid #565565;
  padding-bottom: 16px;
}

nav.folding .search-results::before {
  content: "Results";
  display: block;
  margin-inline-start: 8px;
  font-weight: 600;
  margin-block-end: 16px;
  color: #565565;
}

nav.folding .search-results .type {
  margin-inline-start: 8px;
  text-transform: uppercase;
  font-weight: 600;
  font-size: 12px;
  color: #565565;
}

nav.folding .search-results a {
  margin-block-end: 4px !important;
}

/* On this page navigation in right side bar */

#page-overview {
  margin-top: 64px;
  color: #565565;
  font-weight: 600;
  position: sticky;
  align-self: start;
  top: 24px;
  box-sizing: border-box;
  max-height: calc(100vh - 24px);
  overflow: hidden auto;
  padding-inline-start: 4px;
}

