// Support for showing code blocks in one of three modes:
// - Source only via `source`
// - Preview only via `preview`
// - Source + Preview via `example`
//
// Cooperates with `docs/src/example.rs`.

#import "system.typ": colors, sizes
#import "base.typ": folding-details, labelled, small

// Shared styling properties for all elements with a "boxy" look.
#let radius = 2pt
#let padding = 0.9em
#let border = 0.5pt + colors.light-gray.shade-50

// A generic block with a boxy border.
#let boxy-block(..args) = block(
  stroke: border,
  radius: 2pt,
  clip: true,
  ..args,
)

// A block that is styled like an example.
#let example-like-block(..args) = boxy-block(
  width: 100%,
  inset: padding,
  fill: colors.genuine.white,
  ..args,
)

// Takes a raw block and processes `>>>` and `<<<` markers in them for display.
// The `>>>` marker indicates that a line is display-only while the `<<<` marker
// indices a compile-only line. This function applies the display part (trimming
// the former marker and stripping lines with the latter marker) while the code
// in `example.rs` deals with the markers in the opposite way.
#let with-hidden-lines(it) = {
  assert(it.at("lang", default: none) in (none, "typ", "example"))
  assert.eq(it.block, true)

  // Process the markers.
  let display = ""
  for line in it.text.split("\n") {
    if line.starts-with(">>>") {
      continue
    }

    if line.starts-with("<<< ") {
      line = line.slice(4)
    }

    display += line
    display += "\n"
  }

  // Applies the `<_stop>` label so that the reconstructed raw block is not
  // again affected by `source` show rules. A bit of a hack ...
  labelled(raw(display, lang: "typ", block: true), <_stop>)
}

// Nicely displays the raw block.
#let source(it) = {
  if it.at("label", default: none) == <_stop> {
    return it
  }

  context if target() == "paged" {
    set text(size: sizes.mono)
    example-like-block(if it.lang == "typ" {
      with-hidden-lines(it)
    } else {
      it
    })
  } else {
    it
  }
}

// Displays the rendering of a raw block containing Typst markup.
#let preview(it, ..args) = context {
  let pages = stdx.compile-example(it, ..args)
  context if target() == "paged" {
    align(center, block(
      stroke: border,
      radius: radius,
      clip: true,
      stack(dir: ttb, spacing: 0.5em, ..pages),
    ))
  } else {
    html.div(class: "previewed-code", {
      html.div(class: "preview", pages.join())
    })
  }
}

// Displays a left/right or top/bottom (depending on content) side-by-side
// view of Typst markup and its paged output.
#let example(
  it,
  // Note: Must be `none` if `folding: false`.
  title: none,
  // Whether the example is folding in the HTML version. If `auto`, folds if the
  // example has a `title`.
  folding: auto,
  // Whether the folding example is open by default (vs collapsed).
  // Only applies of `folding` resolves to `true`.
  open: false,
  ..args,
) = context {
  show: rest => if target() == "paged" {
    if title != none {
      align(right, block(
        small[Example #sym.dot.c #text(weight: 500, title)],
        sticky: true,
        below: 0.65em,
      ))
    }
    rest
  } else {
    if folding == true or (folding == auto and title != none) {
      folding-details(
        title: [View example] + if title != none [: #title],
        open: open,
        rest,
      )
    } else {
      assert.eq(title, none)
      rest
    }
  }

  let pages = stdx.compile-example(it, ..args)
  if target() == "paged" {
    layout(region => {
      let source = text(size: sizes.mono, with-hidden-lines(it))
      let available = region.width / 2 - 2 * padding.to-absolute()
      let wide = measure(source).width > available
      block(
        stroke: border,
        radius: radius,
        clip: true,
        grid(
          columns: if wide { 100% } else { (1fr, 1fr) },
          grid.cell(
            inset: padding,
            fill: colors.genuine.white,
            source,
          ),
          grid.cell(
            inset: padding,
            fill: colors.light-gray.shade-10,
            stroke: (
              (if wide { "top" } else { "left" }): border,
            ),
            align: center + horizon,
            stack(dir: ttb, spacing: 0.5em, ..pages),
          )
        ),
      )
    })
  } else {
    html.div(class: "previewed-code", {
      with-hidden-lines(it)
      html.div(class: "preview", pages.join())
    })
  }
}

files.docs/components/figure.typ:
// Defines functions for showing figures in the documentation.

#import "base.typ": constrain
#import "example.typ": boxy-block

// Displays a figure in the documentation.
#let docs-figure(
  // The name of the image file in typst-dev-assets.
  filename,
  // Alt text for the image. Required.
  alt: none,
  // A rough cross-target specification of how wide the image should be.
  //
  // In the HTML version, this correspond to pixels. In the paged version it's
  // multiplied with 0.75pt to define a max width.
  width: none,
  // Whether to render a shadow in the web documentation (or a stroke in the
  // paged one). Will typically be the case, but some things like screenshots
  // may come with their own baked shadow.
  shadow: true,
) = {
  assert.ne(alt, none, message: "alt text is required")
  let img = image(stdx.read-dev-asset(filename))
  context if target() == "paged" {
    set align(center)
    let ratio = 0.75pt
    show: rest => if width != none {
      constrain(width: width * ratio, rest)
    } else {
      rest
    }

    if shadow {
      figure(boxy-block(img))
    } else {
      figure(img)
    }
  } else {
    html.figure(
      ..if shadow { (class: "shadow") },
      ..if width != none { (style: "width: " + str(width) + "px") },
      img,
    )
  }
}

// Displays two figures side-by-side.
#let side-by-side(l, r) = context {
  if target() == "paged" {
    grid(
      columns: (1fr, 1fr),
      gutter: 0.5em,
      l, r,
    )
  } else {
    html.div(class: "side-by-side", l + r)
  }
}

files.docs/components/footnote.typ:
// Built-in footnotes in HTML do not support a custom head (which we write).
// Also, we want to have footnotes scoped to small excerpts of content. This
// minimal footnote implementation is heavily based on the built-in one, but
// adds this extra feature.

// Creates a listing of all footnotes that are descendants of the element
// with the location `scope`.
#let footnote-container(scope) = context {
  let notes = query(stdx.selector-within(footnote, scope))
  if notes.len() == 0 { return }
  html.elem("section", attrs: (role: "doc-endnotes"), {
    for note in notes {
      let num = counter(footnote).display(note.numbering, at: note.location())
      enum.item({
        html.elem(
          "sup",
          attrs: (role: "doc-backlink"),
          link(note.location())[#num],
        )
        note.body
      })
    }
  })
}

// Can be applied with `show footnote`.
#let footnote-rule(it) = context {
  h(0pt, weak: true)
  // Would be a bit nicer to link to the `li` element, but this is good enough.
  let dest = locate(link.where(dest: it.location()))
  let nums = counter(footnote).display(it.numbering, at: it.location())
  html.elem("sup", attrs: (role: "doc-noteref"), link(dest, nums))
}

// Wraps content and creates a footnote listing at the bottom of it.
#let with-footnotes(body) = context {
  // Reset the footnote counter.
  counter(footnote).update(())
  body
  // Create a footnote container that lists all footnotes within this context
  // block. (That's what the `here()` refers to.)
  footnote-container(here())
}

files.docs/components/linking.typ:
// The documentation's cross-referencing system.
//
// Instead of directly referencing elements, we reference _definitions._ A
// definition target is either a label or a value from the standard library. In
// the second case, a canonical label is derived (see `std-path-of`).
//
// = Cross-references in the Typst documentation
// Across the documentation, the following convention is used for definition
// targets:
//
// - The docs for an std value are always referenced with its canonical std
//   path, e.g. `@figure`, `@calc.max`, `@math.attach`, `@str.codepoints`, or
//   `@outline.entry.indented`. Constructors are referenced with the special
//   `.constructor` path, e.g. `@int.constructor`.
// - A chapter is referenced with its HTML route, but replacing slashes with
//   `:`, e.g. `@guides:accessibility`.
// - A subheading in the docs for a value _or_ a chapter is referenced by taking
//   the label for the base and the label of the subheading and joining them
//   with `:`, e.g. `@heading:syntax` or `@guides:tables:column-sizes`.
// - A category is typically referenced via its route (e.g.
//   `@reference:foundations, but if it's tied to a definition, that takes
//   precedence (e.g. `@html` or `@math:function-calls`.
//
// A bare reference always renders the default `title` of the definition
// (monospaced path for std values, title for headings/chapters). If the
// reference has a supplement, it replaces the `title`.
//
// Compared to Typst's built-in referencing system, this custom one has two
// primary benefits:
// - We can attach a short, local, potentially duplicate labels to headings
//   (e.g. `<reading-order>`), also giving us a nice HTML id in the process, but
//   reference them with a fully qualified labels like
//   `<guides:accessibility:reading-order>`. In the future, something like this
//   might become possible with the built-in system, see
//   https://github.com/typst/typst/issues/7998 .
// - We can associate definitions with std values and let the system take care
//   of deriving canonical labels instead of having to build up complex labels
//   in the code that renders the relevant part of the std docs.
//
// = Registering definitions
// Definitions can be added anywhere in the docs with `register-def`.
// Frequently, this happens in heading show rules as that's where the relevant
// location is available. A definition consists of
// - a target (through which it can be referenced)
// - a destination (where it is defined); this is a location or, in HTML in some
//   cases, a route
// - a title (with which it a reference to it is displayed by default).
//
// = Retrieving definitions
// To retrieve a definition, you can use `def-metadata` (to get both the
// destination and the title) or `def-dest` (to get just the former). To link to
// a definition, you can use the `def` function.

#import "base.typ": labelled
#import "reflect.typ": std-path-of

// Returns the label with which a definition can be referenced in the docs.
//
// - If the `def-target` is a value, attempts to locate its path in the standard
//   library and returns the canonical label for it.
// - If the `def-target` is already a label, returns it unchanged.
#let def-label(def-target) = {
  if type(def-target) == label {
    def-target
  } else {
    label(std-path-of(def-target))
  }
}

// Retrieves the metadata for a definition.
//
// Returns a pair of a destination and a title. Requires context.
#let def-metadata(def-target) = {
  let def-label = def-label(def-target)
  let targets = query(selector.and(metadata, def-label))
  let len = targets.len()
  if len == 1 {
    targets.first().value
  } else if len == 0 {
    panic("found no definition for: " + repr(def-label))
  } else {
    panic({
      "found multiple definitions for: "
      repr(def-label)
      " ("
      targets
        .map(m => if type(m.value) == str { m.value } else { repr(m.value) })
        .join(", ")
      ")"
    })
  }
}

// Retrieves the linking destination for a definition.
#let def-dest(def-target) = def-metadata(def-target).first()

// Registers the destination under which a definition is documented.
#let register-def(
  // Either a label or a value that is defined in the standard library.
  def-target,
  // Where the target is documented.
  //
  // May be either a `location` or a route (the latter only in the HTML version
  // where both variants are used).
  dest,
  // What a reference to the target should display. Defaults to just the
  // resolved label's value in raw (e.g. `@int` => `` `int` ``), but could be
  // set to something else, like a heading's body (e.g.
  // `@introduction` => `[Introduction]`).
  title: auto,
) = {
  let def-label = def-label(def-target)
  if title == auto {
    title = raw(str(def-label))
  }
  labelled(metadata((dest, title)), def-label)
}

files.docs/components/live.typ:
// Processes hot reloadable Typst documentation comments in Rust files.
//
// Cooperates with `docs/src/live.rs`.

#import "base.typ": short-or-long
#import "example.typ": example
#import "figure.typ": docs-figure
#import "table.typ": docs-table

// The definitions that are available in Rust doc comments.
#let scope = (
  example: example,
  docs-figure: docs-figure,
  docs-table: docs-table,
  short-or-long: short-or-long,
)

// Returns a dictionary with all live-loaded docs in the Rust file at the given
// path.
//
// This is a separate function so that it's memoized per path.
#let live-docs-at-path(path) = stdx.docs-in-source(read(path))

// Processes docs content for a doc comment in the Rust sources.
//
// Takes the static docs markup and a def site key for hot reload. If the key is
// not `none`, attempts to load a live version of the docs markup from the Rust
// sources.
//
// In both cases, evaluates the markup.
#let live-docs(
  // The static docs content baked into the executable.
  markup,
  // The key for the native definition. May be `none`.
  //
  // See `DefSite::key` for more information.
  def-site,
) = {
  if def-site == none {
    return eval(markup, scope: scope, mode: "markup")
  }

  let live = live-docs-at-path(def-site.path)
  if def-site.key not in live {
    panic("def site was not found:", def-site)
  }

  let (markup, ranges) = live.at(def-site.key)
  stdx.eval-mapped(
    markup,
    def-site.path,
    ranges,
    mode: "markup",
    scope: scope,
  )
}

files.docs/components/nav.typ:
// Navigation components for the HTML version.
//
// Defines
// - `nav-folding`: The collapsible navigation on the left
// - `nav-breadcrumbs`: The docs "path" at the top
// - `nav-on-this-page`: The outline on the right
// - `nav-prev-next`: The navigation buttons on the bottom

#import "base.typ": (
  icon, inline-style, labelled, search-box, with-short-versions,
)

// Registers a section (not a page!) in the nav.
//
// Used for things like "Language" and "Library".
#let nav-separation(depth: 2, title) = labelled(
  metadata((
    title: title,
    depth: depth,
  )),
  <metadata-nav-separation>,
)

// Nav items at a specific depth.
#let nav-items(
  items,
  current,
  is-expanded,
) = html.ul(
  style: inline-style(
    overflow: "visible hidden",
    ..if is-expanded {
      (max-height: "none", pointer-events: "auto", opacity: "1")
    } else {
      (max-height: "0px", pointer-events: "none", opacity: "0")
    },
  ),
  {
    let i = 0
    let len = items.len()
    while i < len {
      let item = items.at(i)
      i += 1
      let k = i
      while i < len and item.depth < items.at(i).depth {
        i += 1
      }

      if "route" in item {
        let has-children = k < i
        let is-current = item.route == current
        let is-expanded = has-children and current.starts-with(item.route)
        html.li(aria-expanded: is-expanded, {
          html.a(
            href: item.route,
            item.title,
            ..if item.route == current { (aria-current: "page") },
          )
          if k < i {
            html.button(icon(16, "chevron-right", "Expand"))
            nav-items(items.slice(k, i), current, is-expanded)
          }
        })
      } else {
        html.li(class: "category", item.title)
      }
    }
  },
)

// The folding navigation on the left of the docs.
#let nav-folding(current) = html.nav(class: "folding", context {
  html.button(class: "close", icon(16, "close", "Close"))
  search-box(id: "docs-search", placeholder: "Search (S)")
  html.ul(id: "search-results", class: "search-results hidden")
  let items = query(selector.or(
    <metadata-page>,
    <metadata-nav-separation>,
  )).map(meta => meta.value)
  nav-items(items, current, true)
})

// Maps from page routes to their titles.
#let title-map() = {
  let pages = query(<metadata-page>)
  pages.map(page => (page.value.route, page.value.title)).to-dict()
}

// The breadcrumbs at the top of the page.
#let nav-breadcrumbs(route) = html.ul(
  class: "breadcrumbs",
  aria-label: "Breadcrumbs",
  context {
    html.li(class: "root", html.a(
      href: stdx.config.content-base,
      icon(16, "docs-dark", "Docs"),
    ))
    let titles = title-map()
    for m in route.matches("/") {
      let parent = route.slice(0, m.end)
      let title = titles.at(parent, default: none)
      if title == none or title == "Overview" { continue }
      html.li(aria-hidden: true, icon(16, "chevron-right", ""))
      html.li(html.a(href: parent, title))
    }
  },
)

// Outline items at a specific depth.
#let nav-on-this-page-items(items) = html.ul({
  let i = 0
  let len = items.len()
  while i < len {
    let item = items.at(i)
    i += 1
    let k = i
    while i < len and item.level < items.at(i).level {
      i += 1
    }
    html.li({
      link(item.dest, item.body)
      if k < i {
        let children = items.slice(k, i)
        nav-on-this-page-items(children)
      }
    })
  }
})

// An outline for a single web page, on the right of the page.
#let nav-on-this-page(scope) = context {
  let items = ()

  let titles = query(stdx.selector-within(
    selector.and(title, <summary>),
    scope,
  ))
  if titles.len() > 0 {
    let dest = titles.first().location()
    items.push((dest: dest, level: 1, body: [Summary]))
  }

  items += query(stdx.selector-within(
    heading.where(outlined: true),
    scope,
  )).map(m => (dest: m.location(), level: m.level, body: m.body))

  if items.len() == 0 { return }

  html.nav(id: "page-overview", {
    strong[On this page]
    with-short-versions(nav-on-this-page-items(items))
  })
}

// The nav buttons on normal pages.
#let nav-button(
  href: none,
  icon: none,
  class: none,
  title: none,
  hint: none,
) = html.a(
  href: href,
  class: "nav-button " + class,
  {
    icon
    html.div({
      html.span(class: "page-title", title)
      html.span(class: "hint", hint)
    })
  },
)

// The big nav buttons on the overview page.
#let big-nav-button(
  href: none,
  icon: none,
  title: none,
  description: none,
) = html.a(
  href: href,
  class: "nav-button",
  {
    icon
    html.strong(title)
    html.p(description)
  },
)

// The navigation buttons at the bottom of the page.
#let nav-prev-next() = html.div(class: "page-end-buttons", context {
  let prev = query(selector(<metadata-page>).before(here()))
  if prev.len() > 1 {
    let (title, route) = prev.at(-2).value
    nav-button(
      icon: icon(16, "chevron-right", "←"),
      class: "previous",
      hint: [Previous page],
      href: route,
      title: title,
    )
  }
  let next = query(selector(<metadata-page>).after(here()))
  if next.len() > 0 {
    let (title, route) = next.first().value
    nav-button(
      icon: icon(16, "chevron-right", "→"),
      class: "next",
      hint: [Next page],
      href: route,
      title: title,
    )
  }
})

