// Defines metadata for docs search in the web version.
//
// Cooperates with `docs/src/search.rs`.

#import "base.typ": labelled

// Defines one searchable entry (a search _index item_) in the documentation,
// i.e. one potential search hit.
//
// See `IndexItem` in the Rust sources for more details on the parameters.
#let register-index-item(
  kind: none,
  title: none,
  dest: none,
  keywords: (),
) = labelled(
  metadata((
    kind: kind,
    title: title,
    dest: dest,
    keywords: keywords,
  )),
  <metadata-index-item>,
)

files.docs/components/section.typ:
#import "base.typ": (
  classnames, heading-offset, icon, labelled, short-or-long, title-state,
  tooltip-counter,
)
#import "linking.typ": register-def
#import "nav.typ": nav-breadcrumbs, nav-folding, nav-on-this-page, nav-prev-next
#import "search.typ": register-index-item
#import "styling.typ": prose-styling, styling

// One section in the paged documentation.
#let paged-section(
  title-fmt: none,
  title-content: none,
  def-title: none,
  introduction: none,
  def-target: none,
  body,
) = {
  title-state.update(none)

  // New section starts on a new page.
  pagebreak(weak: true)

  // Section heading.
  {
    show heading: it => {
      let loc = it.location()

      // All sections referenceable under their definition target. We want to
      // link to the section heading.
      if def-target != none {
        register-def(def-target, loc, title: def-title)
      }

      // Update what's shown in the page header.
      title-state.update({
        if it.numbering != none {
          counter(heading).display(it.numbering, at: loc)
        }
        [ ]
        title-fmt
      })

      it
    }
    heading(title-content)
  }

  let offset = 1

  // If requested, add an invisible introduction heading and increase the
  // heading nesting depth by one extra.
  if introduction {
    show heading: none
    heading(depth: 2, numbering: none)[Introduction]
    offset += 1
  }

  heading-offset(offset, body)
}

// One section (page) in the website documentation.
#let html-section(
  title: none,
  title-content: none,
  has-summary: none,
  def-title: none,
  route: none,
  def-target: none,
  class: none,
  nav-buttons: none,
  kind: none,
  keywords: none,
  description: none,
  body,
) = context {
  let depth = calc.max(
    route.split("/").filter(seg => seg.len() != 0).len(),
    1,
  )

  let route = stdx.config.content-base + route.trim("/")
  if not route.ends-with("/") {
    route += "/"
  }

  if def-target != none {
    register-def(def-target, route, title: def-title)
  }

  // Reset the tooltip counter for each page.
  tooltip-counter.update((0,))

  document(route + "index.html", title: title, html.html({
    // The index item is placed here so that all body text of this HTML document
    // is considered part of this index item.
    register-index-item(
      kind: kind,
      title: title,
      dest: route,
      keywords: keywords,
    )

    // This metadata is used for the section navigation.
    labelled(
      metadata((route: route, title: title, depth: depth)),
      <metadata-page>,
    )

    html.head({
      html.meta(charset: "utf-8")
      html.meta(
        name: "viewport",
        content: "width=device-width, initial-scale=1",
      )
      html.meta(name: "description", content: description)
      html.meta(name: "theme-color", content: "#239dad")
      html.meta(name: "robots", content: "noindex")
      html.link(href: stdx.config.asset-base + "base.css", rel: "stylesheet")
      html.link(href: stdx.config.asset-base + "docs.css", rel: "stylesheet")
      html.script(type: "module", src: stdx.config.asset-base + "docs.js")
      html.title(title + " - Typst Documentation")
      // TODO: More to come here
    })

    html.body(class: classnames("docs", class), {
      html.header(class: "w695", {
        html.button(
          class: "hamburger",
          icon(16, "hamburger-dark", "Open navigation"),
        )
      })
      html.div(class: "main-grid", {
        nav-folding(route)
        context {
          html.main({
            nav-breadcrumbs(route)
            labelled(std.title(title-content), if has-summary { <summary> })
            body
            nav-buttons
          })
          nav-on-this-page(here())
        }
      })
    })
  }))
}

// One section in the documentation.
//
// Corresponds to one page in the HTML version and to one subsection in paged
// export. The depth of the section in PDF export varies. For instance, "Syntax"
// is a section at depth 2, but "Float" is also a section, at depth 3.
#let docs-section(
  // The plain-text title of the section.
  title: none,
  // The richly formatted title of the section.
  title-fmt: auto,
  // An optional subtitle for the section, displayed within the heading.
  // This is, for instance, used for the "Element" suffix.
  subtitle: none,
  // Whether the page outline should have a "Summary" entry.
  has-summary: false,
  // Whether the section is an introductory section of a larger one. If so, it
  // will get a hidden "Introduction" heading in the PDF outline and the
  // headings in its body skip an extra level.
  introduction: false,

  // The URL path of the section in the web version. Will be amended to the docs
  // base path.
  route: none,
  // The definition target for the section. See `linking.typ` for more
  // information.
  def-target: none,

  // CSS class(es) to apply to the section's HTML page.
  class: none,
  // The navigation buttons at the bottom of the HTML page.
  nav-buttons: nav-prev-next(),

  // The kind of section. This is displayed in the search result for the page.
  kind: none,
  // Keywords for the page. The page can be found in search with these.
  keywords: (),
  // The plain-text description of the HTML page.
  description: none,

  // The content of the section.
  body,
) = {
  assert.ne(title, none, message: "title is required")
  assert.eq(type(title), str, message: "title must be a string")
  assert.ne(route, none, message: "route is required")
  assert.ne(def-target, none, message: "definition target is required")
  assert.ne(description, none, message: "description is required")
  assert.eq(type(description), str, message: "description must be a string")
  assert.ne(kind, none, message: "kind is required")
  assert.eq(type(keywords), array, message: "keywords must be an array")
  assert(route.starts-with("/"), message: "route must start with slash")

  if title-fmt == auto {
    title-fmt = title
  }

  // The title under which the definition will be referenced. If the target is a
  // label, we use the section title. If the target is an std value, we use
  // the default (monospace raw of the target value's path in std).
  let def-title = if type(def-target) == label { title } else { auto }
  let title-content = short-or-long(title, title-fmt + subtitle)

  context if target() == "paged" {
    paged-section(
      title-fmt: title-fmt,
      title-content: title-content,
      def-title: def-title,
      introduction: introduction,
      def-target: def-target,
      body,
    )
  } else {
    html-section(
      title: title,
      title-content: title-content,
      has-summary: has-summary,
      def-title: def-title,
      route: route,
      def-target: def-target,
      class: class,
      nav-buttons: nav-buttons,
      kind: kind,
      keywords: keywords,
      description: description,
      body,
    )
  }
}

// A section of kind "Chapter".
//
// Receives an automatic definition target based on the `route` (where slashes
// are replaced with `:`) and applies prose styling to the body content.
//
// This is used for prose sections like in the tutorial, language reference, and
// guides.
#let docs-chapter(
  route: none,
  def-target: none,
  ..args,
  body,
) = {
  assert.ne(route, none, message: "route is required")

  if def-target == none {
    def-target = label(route.trim("/", at: start).replace("/", ":"))
  }

  docs-section(
    route: route,
    def-target: def-target,
    ..args,
    kind: "Chapter",
    prose-styling(body, base-target: def-target),
  )
}

// An outline for a single section in the docs.
#let section-outline(title: auto, label: none) = {
  assert.ne(label, none, message: "label is required")
  labelled(heading(title, outlined: false), label)

  context if target() == "html" {
    let before = query(selector(<metadata-page>).before(here()))
    let after = query(selector(<metadata-page>).after(here()))
    let min = before.last().value.depth
    let i = 0
    for m in after {
      if m.value.depth == min + 1 {
        list.item(link(m.value.route, m.value.title))
      } else if m.value.depth <= min {
        break
      }
    }
  } else {
    let level = 2
    let candidates = heading.where(level: level)
    let parents = heading.where(level: level - 1)
    outline(
      title: none,
      target: candidates.after(here()).before(parents.after(here())),
      indent: 0pt,
      depth: level,
    )
  }
}

files.docs/components/styling.typ:
// Defines the set of styling rules for
// - docs content at large
// - "prose" content, i.e. hand-written content in chapters or individual
//   element docs (as opposed to componentized non-prose content).

#import "system.typ": colors, fonts, sizes
#import "base.typ": labelled, small, title-state, with-short-versions
#import "example.typ": example, preview, source
#import "footnote.typ": footnote-rule, with-footnotes
#import "linking.typ": def-label, def-metadata, register-def

// The part of the global styling that applies to the paged version.
#let paged-styling(body) = {
  set page(margin: (x: 3cm, y: 2.5cm))
  set text(font: (fonts.body, ..fonts.fallback), size: sizes.body)
  set list(marker: [--])
  set underline(offset: 0.2em)
  set footnote(numbering: "[A]")
  set table.cell(inset: 4pt)

  show title: set text(28pt)

  show heading.where(outlined: true): set heading(numbering: "1.1.1/1.1")
  show heading.where(level: 1): it => pagebreak(weak: true) + it
  show heading.where(level: 1): set text(18pt)
  show heading.where(level: 2): set text(15pt)
  show heading.where(level: 3): set text(13pt)
  show heading.where(level: 4): set text(11pt)
  show heading.where(level: 5): set text(10pt)
  show heading: set block(below: 1em)
  show heading: it => block({
    if it.numbering != none {
      set text(size: sizes.body, weight: "regular")
      let nums = counter(heading).at(it.location())
      let fmt = if nums.len() <= 3 {
        numbering("1.1", ..nums)
      } else {
        numbering("/1.1", ..nums.slice(3))
      }
      box(width: 0pt, align(right, box(width: 3em, {
        small(fmt)
        h(0.5em)
      })))
    }
    it.body
  })

  // Justifying and hyphenating in tables doesn't look great.
  show table: set par(justify: false)

  // Cancel default raw scaling. We reapply it eventually, but because we do so
  // much stuff with raw blocks (also sometimes recreating them), it keeps
  // interfering. Replacing show rules would probably help. We intentionally
  // hardcode 0.8 here instead of using `sizes.mono` because it's unrelated.
  // Here, we cancel the compiler default.
  show raw: set text(size: 1em / 0.8, font: (fonts.mono, ..fonts.fallback))

  // Outline entries pick the short versions of content which makes use of
  // the `short-or-long` component.
  show outline: with-short-versions

  include "preface.typ"

  // Header & footer only start after the preface.
  set page(
    numbering: "1",
    header: {
      counter(footnote).update(())
      context {
        let title = title-state.get()
        if title != none {
          align(right, small(title))
        }
      }
    },
    footer: align(right, small(context counter(page).display())),
  )

  {
    show outline: set heading(bookmarked: true)
    show outline.entry.where(level: 1): set outline.entry(fill: none)
    show outline.entry.where(level: 1): set block(above: 1.2em, below: 0.8em)
    show outline.entry.where(level: 1): set text(
      size: 1.2em,
      weight: "bold",
      fill: colors.dark-gray.shade-60,
    )
    outline(
      depth: 3,
      indent: n => 1.5em * n,
    )
  }

  body
}

// The part of the global styling that applies to the HTML version.
#let html-styling(body) = {
  // Without this, we can't link to headings.
  show heading: it => {
    assert(it.has("label"), message: "headings must be labelled")
    it
  }
  body
}

// Global styling that is applied to the full docs.
#let styling(body) = {
  set document(
    title: "Typst Documentation (Version: " + str(sys.version) + ")",
    author: (
      "Laurenz Mädje",
      "Martin Haug",
      "The Typst Project Developers",
    ),
  )

  show ref: it => {
    let (dest, title) = def-metadata(it.target)
    if it.supplement == auto {
      link(dest, title)
    } else {
      link(dest, it.supplement)
    }
  }

  show raw.where(block: true): source
  show raw.where(lang: "example"): example
  show raw.where(lang: "preview"): preview
  show raw.where(block: false): it => {
    if it.lang == none {
      let t = it.text
      if t.starts-with("{") and t.ends-with("}") {
        return raw(t.slice(1, -1), lang: "typc")
      }
      if t.starts-with("[") and t.ends-with("]") {
        return raw(t.slice(1, -1), lang: "typ")
      }
    }
    // Only now apply scaling to avoid it being applied twice for
    // replaced raw blocks.
    set text(size: sizes.mono)
    it
  }

  context if target() == "paged" {
    paged-styling(body)
  } else {
    html-styling(body)
  }
}

// The part of `prose-styling` that applies to the paged version.
#let paged-prose-styling(body) = {
  set par(justify: true)

  show link: underline
  show link: it => {
    it
    if type(it.dest) == str and it.at("label", default: none) != <_stop> {
      footnote(labelled(link(it.dest), <_stop>))
    } else if type(it.dest) == location {
      let element = query(it.dest).first()
      if element.func() == heading and element.numbering != none {
        super(text(
          fill: colors.dark-gray.shade-05,
          counter(heading).display(
            element.numbering.trim(".", at: end),
            at: element.location(),
          ),
        ))
      }
    }
  }

  body
}

// The part of `prose-styling` that applies to the HTML version.
#let html-prose-styling(body) = {
  show footnote: footnote-rule
  show: with-footnotes
  body
}

// Styling that is applied to hand-written content as opposed to componentized
// elements.
#let prose-styling(
  // A def target (label or std definition) that is prepended to heading labels
  // for referencing. If `body` contains a heading labelled `<syntax>` and the
  // base target is `<heading>`, then, the section can be referenced as
  // `@syntax:heading`.
  base-target: none,
  body,
) = {
  show: rest => if base-target != none {
    show heading: it => {
      register-def(
        label(str(def-label(base-target)) + ":" + str(it.label)),
        it.location(),
        title: it.body,
      )
      it
    }
    rest
  } else {
    rest
  }

  context if target() == "paged" {
    paged-prose-styling(body)
  } else {
    html-prose-styling(body)
  }
}

